var ALGOS=['MD5','SHA-1','SHA-256','SHA-512'];
function toHex(buf){return Array.prototype.map.call(new Uint8Array(buf),function(b){return ('0'+b.toString(16)).slice(-2);}).join('');}

/* MD5, needed because the browser crypto API does not provide it */
var MD5K=[],MD5S=[7,12,17,22,7,12,17,22,7,12,17,22,7,12,17,22,5,9,14,20,5,9,14,20,5,9,14,20,5,9,14,20,4,11,16,23,4,11,16,23,4,11,16,23,4,11,16,23,6,10,15,21,6,10,15,21,6,10,15,21,6,10,15,21];
for(var ki=0;ki<64;ki++){MD5K[ki]=Math.floor(Math.abs(Math.sin(ki+1))*4294967296);}
function rotl(x,c){return (x<<c)|(x>>>(32-c));}
function md5(bytes){
  var len=bytes.length,nblk=((len+8)>>6)+1,m=new Int32Array(nblk*16);
  for(var i=0;i<len;i++){m[i>>2]|=bytes[i]<<((i%4)*8);}
  m[len>>2]|=0x80<<((len%4)*8);
  m[nblk*16-2]=len*8;
  var a0=1732584193,b0=-271733879,c0=-1732584194,d0=271733878;
  for(var blk=0;blk<nblk;blk++){
    var off=blk*16,A=a0,B=b0,C=c0,D=d0;
    for(var j=0;j<64;j++){
      var F,g;
      if(j<16){F=(B&C)|(~B&D);g=j;}
      else if(j<32){F=(D&B)|(~D&C);g=(5*j+1)%16;}
      else if(j<48){F=B^C^D;g=(3*j+5)%16;}
      else {F=C^(B|~D);g=(7*j)%16;}
      F=(F+A+MD5K[j]+m[off+g])|0;
      A=D;D=C;C=B;B=(B+rotl(F,MD5S[j]))|0;
    }
    a0=(a0+A)|0;b0=(b0+B)|0;c0=(c0+C)|0;d0=(d0+D)|0;
  }
  var out=new Uint8Array(16),vals=[a0,b0,c0,d0];
  for(var v=0;v<4;v++){for(var k=0;k<4;k++){out[v*4+k]=(vals[v]>>>(k*8))&255;}}
  return toHex(out);
}
async function hashAll(){
  var text=document.getElementById('in').value;
  var bytes=new TextEncoder().encode(text);
  var box=document.getElementById('rows');
  box.innerHTML='';
  for(var i=0;i<ALGOS.length;i++){
    var name=ALGOS[i],hex;
    if(name==='MD5'){hex=md5(bytes);}
    else{
      try{hex=toHex(await crypto.subtle.digest(name,bytes));}
      catch(e){hex='Not supported in this browser';}
    }
    var row=document.createElement('div');row.className='hrow';
    row.innerHTML='<div class="hh"><b>'+name+'</b><button data-h="'+hex+'">Copy</button></div><div class="hval">'+hex+'</div>';
    box.appendChild(row);
  }
  document.getElementById('note').textContent='Hashed '+bytes.length+' bytes. The same input always gives the same hash.';
  WT.resize();
}
document.getElementById('rows').addEventListener('click',function(e){
  var b=e.target.closest('button[data-h]');if(!b)return;
  var ok=WT.copy(b.getAttribute('data-h'));
  document.getElementById('note').textContent=ok?'Hash copied to clipboard.':'Copy failed, select the hash instead.';
});
document.getElementById('go').addEventListener('click',hashAll);
document.getElementById('in').addEventListener('input',hashAll);
document.getElementById('clear').addEventListener('click',function(){
  document.getElementById('in').value='';hashAll();
});
